{
  "model": "openai/gpt-4o-mini",
  "state": "Customer: I was double charged and support ignored my emails. I want a refund now or I cancel.",
  "questions": {
    "is_frustrated": {
      "kind": "noul",
      "instructions": "Is the customer frustrated?"
    },
    "category": {
      "kind": "choice",
      "instructions": "Pick the ticket category",
      "criteria": {
        "billing": "charges and refunds",
        "bug": "product defects",
        "other": "anything else"
      }
    },
    "urgency": {
      "kind": "score",
      "instructions": "Rate how urgently this needs a human reply",
      "criteria": [
        "low",
        "medium",
        "high"
      ]
    }
  }
}

{
  "model": "openai/gpt-4o-mini",
  "state": "Customer message: I was double charged last month and nobody replied to my two emails. I want a refund today or I am cancelling.",
  "questions": {
    "approve_review": {
      "kind": "noul",
      "instructions": "Should this ticket get a billing review?",
      "criteria": {
        "true": "the customer reports a concrete billing error",
        "false": [
          "no billing problem is described",
          "general inquiry"
        ]
      }
    },
    "pick": {
      "kind": "choice",
      "instructions": "Pick the ticket category. The option names are opaque codes; use the criteria descriptions to decide.",
      "criteria": {
        "opt_a": {
          "rubric": "charges and refunds"
        },
        "opt_b": "product defects",
        "opt_c": null,
        "opt_d": [
          "installation help",
          "how-to setup questions"
        ]
      }
    },
    "urgency": {
      "kind": "score",
      "instructions": "Rate how urgently this needs a human reply",
      "criteria": [
        "can wait a week",
        {
          "level": "should be answered soon"
        },
        [
          "needs a reply today",
          "churn risk"
        ]
      ]
    }
  }
}

{
  "model": "openai/nonexistent-model-xyz",
  "fallbacks": [
    "openai/gpt-4o-mini"
  ],
  "state": "Reply: sounds good, see you at 3pm.",
  "questions": {
    "is_confirmation": {
      "kind": "noul",
      "instructions": "Does this confirm the meeting?"
    }
  }
}

{
  "model": "openai/gpt-4o-mini",
  "state": "Email: verify your password at bank-secure.xyz within 24h.",
  "questions": {
    "is_phishing": {
      "type": "noul",
      "instructions": "Is this phishing?"
    }
  }
}
